package context

import (
	"context"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"

	"github.com/kjmaguire/drydock/internal/safefs"
)

// Hooks let other subsystems (attached expert packs, skills) contribute to a worktree's generated files without this
// package importing them. Both are optional; with neither set the engine behaves exactly as before.

// RepoMapSectionTitle is the title of the repo map section of AGENTS.md (internal/core ext_repomap.go, decision P62).
const RepoMapSectionTitle = "Repository map"

// Section is text contributed to the generated AGENTS.md (attached pack instructions, a note on how to get skills). A
// section with no body is left out of AGENTS.md; when it has a Reason, the manifest records it as left out, with that reason.
type Section struct {
	Title    string
	Body     string
	Source   string // manifest source, for example "pack:cloudflare"
	Reason   string
	Priority int // manifest priority; sections are also ordered by it
}

// ExtraFile is an app-owned file another subsystem wants in the worktree, for example .claude/rules/<name>.md. Path is
// relative with forward slashes. A file that already exists without GeneratedMarker in its first lines belongs to the user and
// is never overwritten.
type ExtraFile struct {
	Path    string
	Content string
	Source  string // manifest source, for example "skill:d1-migrations"
	Reason  string
	// Done (optional) is called after the write was attempted: written is false when the file was left alone.
	Done func(ctx context.Context, written bool)
}

// GeneratedMarker marks a file as generated by Drydock (it may be rewritten).
const GeneratedMarker = "drydock:generated"

// SectionsFunc returns extra AGENTS.md sections for a worktree; worktree is empty when the caller has none.
type SectionsFunc func(ctx context.Context, projectID, worktree string) ([]Section, error)

// FilesFunc returns the extra files for a worktree.
type FilesFunc func(ctx context.Context, projectID, worktree string) ([]ExtraFile, error)

// maxExtraFile bounds how much of an existing file is read to see whether it is one of ours (the marker is in the first lines).
const maxExtraFile = 1 << 20

// extraDirs are the directories whose stale generated files are removed when the set of extra files changes.
var extraDirs = []string{".claude/rules", ".claude/drydock-skills", ".agents/skills"}

func hasMarker(content string) bool {
	head := content
	if len(head) > 2048 {
		head = head[:2048]
	}
	return strings.Contains(head, GeneratedMarker)
}

// safeRel validates an ExtraFile path: relative, forward slashes, no "..", nothing in .git.
func safeRel(p string) (string, bool) {
	if p == "" || strings.ContainsAny(p, "\x00\\:") || strings.HasPrefix(p, "/") {
		return "", false
	}
	parts := strings.Split(p, "/")
	for _, seg := range parts {
		if seg == "" || seg == "." || seg == ".." || strings.EqualFold(seg, ".git") {
			return "", false
		}
	}
	return strings.Join(parts, "/"), true
}

// writeExtras materialises the extra files. It returns the paths written, the paths left alone (the user's own files or
// refused paths) and the manifest items. Symbolic links on the way are never followed: a link in the checkout cannot redirect
// a generated file outside the worktree.
func (e *Engine) writeExtras(ctx context.Context, projectID, worktree string, m *Manifest) (written, skipped []string, err error) {
	if e.Files == nil {
		return nil, nil, nil
	}
	files, err := e.Files(ctx, projectID, worktree)
	if err != nil {
		return nil, nil, err
	}
	sort.Slice(files, func(i, j int) bool { return files[i].Path < files[j].Path })
	want := map[string]bool{}
	for _, f := range files {
		rel, ok := safeRel(f.Path)
		if !ok {
			skipped = append(skipped, f.Path)
			m.Add(f.Source, false, 0, "refused: unsafe path "+f.Path, 5)
			if f.Done != nil {
				f.Done(ctx, false)
			}
			continue
		}
		if pathHasLink(worktree, rel) {
			skipped = append(skipped, rel)
			m.Add(f.Source, false, 0, "refused: a symbolic link on the path "+rel, 5)
			if f.Done != nil {
				f.Done(ctx, false)
			}
			continue
		}
		if cur, rerr := safefs.ReadFile(worktree, rel, maxExtraFile); rerr == nil && !hasMarker(string(cur)) {
			skipped = append(skipped, rel)
			m.Add(f.Source, false, 0, "left alone: "+rel+" is the repository's own file", 5)
			if f.Done != nil {
				f.Done(ctx, false)
			}
			continue
		}
		want[rel] = true
		if err := safefs.MkdirAll(worktree, path.Dir(rel), 0o755); err != nil {
			return written, skipped, err
		}
		if err := safefs.WriteFile(worktree, rel, []byte(f.Content), 0o644); err != nil {
			return written, skipped, err
		}
		written = append(written, rel)
		m.Add(f.Source, true, len(f.Content), firstNonEmpty(f.Reason, "generated file"), 6)
		if f.Done != nil {
			f.Done(ctx, true)
		}
	}
	// generated rule files that are no longer wanted (a skill was rejected since the last write) are removed
	for _, dir := range extraDirs {
		root := filepath.Join(worktree, filepath.FromSlash(dir))
		_ = filepath.WalkDir(root, func(p string, d os.DirEntry, werr error) error {
			if werr != nil || d.IsDir() || d.Type()&os.ModeSymlink != 0 || !strings.HasSuffix(p, ".md") {
				return nil
			}
			rel, rerr := filepath.Rel(worktree, p)
			if rerr != nil {
				return nil
			}
			rel = filepath.ToSlash(rel)
			if want[rel] {
				return nil
			}
			if b, rerr := safefs.ReadFile(worktree, rel, maxExtraFile); rerr == nil && hasMarker(string(b)) {
				_ = safefs.Remove(worktree, rel)
			}
			return nil
		})
	}
	return written, skipped, nil
}

// pathHasLink reports whether any existing component of rel under root is a symbolic link.
func pathHasLink(root, rel string) bool {
	cur := root
	for _, seg := range strings.Split(rel, "/") {
		cur = filepath.Join(cur, seg)
		if fi, err := os.Lstat(cur); err == nil && fi.Mode()&os.ModeSymlink != 0 {
			return true
		}
	}
	return false
}

func firstNonEmpty(a, b string) string {
	if strings.TrimSpace(a) != "" {
		return a
	}
	return b
}
